<?php
namespace App\Http\Controllers\Admin;
use App\Exceptions\CpanelException; use App\Http\Controllers\Controller; use App\Services\{CpanelService,IkontrolInstanceConnectionService,InstanceFilesystemService}; use App\Services\LegacyFc2\FactucareConnectionService; use Throwable;
class ConfigurationController extends Controller {
 public function index(CpanelService $cpanel,FactucareConnectionService $factucare){return view('admin.configuration.index',['configurationStatus'=>['cpanel'=>$cpanel->isConfigured()?'CONFIGURED':'NOT_CONFIGURED','mysql'=>$this->mysqlConfigured()?'CONFIGURED':'NOT_CONFIGURED','filesystem'=>filled(config('ikontrol.instances_root'))?'CONFIGURED':'NOT_CONFIGURED','factucare'=>$factucare->isConfigured()?'CONFIGURED':'NOT_CONFIGURED']]);}
 public function test(string $target,CpanelService $cpanel,InstanceFilesystemService $filesystem,IkontrolInstanceConnectionService $mysql,FactucareConnectionService $factucare){try{$result=match($target){'cpanel'=>$cpanel->testConnection(),'mysql'=>$mysql->testGlobalConnection(),'factucare'=>$factucare->testConnection(),'filesystem'=>$filesystem->rootWritable()?['success'=>true,'status'=>'CONNECTED','message'=>'El root existe y tiene permisos de escritura.']:['success'=>false,'status'=>'ERROR','message'=>'El root no existe o no tiene permisos de escritura.']};return back()->with('diagnostic',['target'=>$target]+$result)->with($result['success']?'success':'error',$result['message']);}catch(CpanelException $e){return back()->with('diagnostic',['target'=>$target]+$e->diagnostic())->with('error',$e->safeMessage());}catch(Throwable){return back()->with('diagnostic',['target'=>$target,'status'=>'ERROR'])->with('error','No fue posible completar la prueba. Revise la configuración.');}}
 private function mysqlConfigured():bool{return filled(config('ikontrol.db.host'))&&filled(config('ikontrol.db.port'))&&filled(config('ikontrol.db.username'))&&config('ikontrol.db.password')!==null;}
}
